sealed abstract case class Contract private (customer: Party, supplier: Party, startDate: LocalDate)
object Contract:
  final case class Invalid(missing: List[String])
  def apply(customer: Party, supplier: Party, startDate: LocalDate): Either[Invalid, Contract] =
    val missing = List(
      Option.unless(customer != supplier)("customer and supplier must differ"),
      Option.unless(!startDate.isBefore(LocalDate.now()))("startDate is in the past")).flatten
    if missing.isEmpty then Right(new Contract(customer, supplier, startDate) {}) else Left(Invalid(missing))

// Client usage - validation gate is the ONLY path to an instance:
val contract = Contract(acme, globex, start)  // Right(Contract) or Left(Invalid(missing))
